// === Tab: mySketch ===
    		// Text as particles
        // Words from Sol LeWitt "Sentences on Conceptual Art", https://www.moma.org/collection/works/146945, 
        // by Henrique Silva, 2023-10-28
        // https://openprocessing.org/sketch/2065046
        // #p5js #generativeart #creativecoding #sollewitt 

        let font;
        'use strict';

        var joinedText;

        var excludedWords = ['the', 'is', 'of', 'a', 'they', 'that', 'an', 'to', 'in', 'his', 'are', 'may', 'and', 'by', 's',
            'it', 'sol', 'its', "than", "cannot", "but", "who", "goes", "rather", "others", "for", "as", "too", "there"]


        function preload() {
            font = loadFont('https://openprocessing.org/sketch/2065046/files/FreeSans.otf');
            joinedText = loadStrings('https://deckard.openprocessing.org/user5362/visual1053499/h907d14b78c742717022d1f171303fbf3/SolLeWitt_sentences.txt');

        }

        let font_size = 36

        const DRAW_BALLS = true;
        const LERP_AMOUNT = 0.0000001;
        var balls = [];


        function setup() {
            createCanvas(windowHeight, windowHeight);

            strokeWeight(2)

            textFont(font);
            textSize(font_size);

            joinedText = joinedText.join(' '); // array para string
            var words = joinedText.match(/\w+/g); // retorna array com as palavras individuais

            let words_ = []
            for (var i = 0; i < words.length; i++) {
                var w = words[i].toLowerCase();
                if (!excludedWords.includes(w))
                    words_.push(w);
            }

            let words_no_duplicates = removeDuplicates(words_)


            words_no_duplicates.forEach(function (item) {
                let v = createVector(random(width - 100), random(100, height-100))
                if (random() < 0.1) balls.push(
                    {
                        pos: v,
                        vel: p5.Vector.fromAngle(random(TAU), 2),
                        bounds: font.textBounds(item, v.x, v.y, font_size),
                        txt: item
                    }
                )


            })


        }

        function removeDuplicates(arr) {
            return arr.filter((item,
                index) => arr.indexOf(item) === index);
        }


        function draw() {
            background(0);
            for (var ball of balls) {
                // add velocity vector
                ball.pos.add(ball.vel);
                ball.bounds = font.textBounds(ball.txt, ball.pos.x, ball.pos.y, font_size)
                // check limits, change signal of velocity vector
                if (ball.bounds.x < 0 || ball.bounds.x + ball.bounds.w > width) {
                    ball.vel.x = -ball.vel.x;
                }
                if (ball.bounds.y < 0 || ball.bounds.y + ball.bounds.h > height) {
                    ball.vel.y = -ball.vel.y;
                }
                let points = []
                if (DRAW_BALLS) {

                    fill(255)
                    noStroke()
                    text(ball.txt, ball.pos.x, ball.pos.y)
							//ellipse(ball.pos.x, ball.pos.y,10,10)

                }
                // check distance with other particles
                for (var ball2 of balls) {
                    if (ball2 == ball) continue;
                    // indexOf index of first element found -> this is for not compare all particles to all particles ->and then check the distance
                    if (balls.indexOf(ball) > balls.indexOf(ball2) && 
						((ball2.pos.x - ball.pos.x) * (ball2.pos.x - ball.pos.x) + 
						 (ball2.pos.y - ball.pos.y) * (ball2.pos.y - ball.pos.y)) < 20000) {
                        noFill()
                        stroke(240, 150, 20);
                        rect(ball.bounds.x, ball.bounds.y, ball.bounds.w, ball.bounds.h)
                        rect(ball2.bounds.x, ball2.bounds.y, ball2.bounds.w, ball2.bounds.h)

                        line(ball.pos.x, ball.pos.y, ball2.pos.x, ball2.pos.y);

                        fill(240, 150, 20);
                        text(ball.txt, ball.pos.x, ball.pos.y)
                        text(ball2.txt, ball2.pos.x, ball2.pos.y)

                    }
                    // lerp linear interpolation of diference vector by LERP_AMOUNT
                    ball.vel.lerp(p5.Vector.sub(ball2.pos, ball.pos), LERP_AMOUNT);
                }
            }

        }

